__NUXT_JSONP__("/it/hollywood", (function(a,b){return {data:[{details:{slug:a,pageTitle:"Hollywood Campus | Mentor Language Institute",pageDescription:"Hollywood è nota per essere il centro dell'industria dell'intrattenimento.",title:"Hollywood Campus",image:"\u002Fimages\u002Flocation\u002Fhollywood\u002Fhollywood-campus.jpg",yt_link:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FuCWlF3puk4Y",subtitle:["\u003Cspan class=\"hutoaka\"\u003EHollywood è nota per essere il centro dell'industria dell'intrattenimento.\u003C\u002Fspan\u003E La cerimonia dei Premi Oscar ha luogo al Dolby Theater a soli due minuti dal nostro campus in Hollywood che precisamente si trova a Hollywood & Highland. A soli due minuti di distanza a piedi da\u002Fper la stazione della metropolitana Hollywood\u002FHighland. Moltissimi eventi, come anteprime di film e cerimonie di apertura, hanno luogo in quest'area. La probabilità di incontrare attori famosi a Hollywood mentre scendono dalle loro limousine all'esterno del Dolby Theater è davvero alta.","I nostri studenti del campus di Hollywood mostrano frequentemente interesse in attività del mondo dell'intrattenimento, quali danza, musica, recitazione, yoga e simili. Il noto Musician's Institute si trova di fronte al nostro campus di Hollywood.","Inoltre, in quest'area sono presenti moltissimi studi di danza come:"],lists:["Musician Institute","Edge Performing Arts","Millennium Dance Complex","Debbie Raynolds","MovementLifestyle","Los Angeles Film School","NY Film Academy"],other_desc:["Hollywood rappresenta una perfetta location rivelandosi una comoda posizione per gli studenti internazionali che spesso si affidano ai trasporti pubblici.","Se hai intenzione di studiare in una classe di moderate dimensioni e allo stesso tempo essere vicino all'industria dell'intrattenimento\u002Fdel cinema\u002Fdello spettacolo, MLI-Hollywood è il posto che fa per te!"],albums:[{title:"Campus",photos:["\u002Fimages\u002Flocation\u002Fhollywood\u002Fcampus-1-th.jpg","\u002Fimages\u002Flocation\u002Fhollywood\u002Fcampus-2-th.jpg"]},{title:b,photos:["\u002Fimages\u002Flocation\u002Fhollywood\u002Fclass-1.jpg","\u002Fimages\u002Flocation\u002Fhollywood\u002Fclass-2.jpg"]}],location:{title:"Location",link:"https:\u002F\u002Fwww.google.com\u002Fmaps\u002Fembed?pb=!1m18!1m12!1m3!1d3303.7636753752786!2d-118.3467233847837!3d34.1011940805926!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x80c2bf239f1c4a45%3A0x6953aa45bd461a42!2sMentor%20Language%20Institute%20-%20Hollywood!5e0!3m2!1sen!2sph!4v1576725075448!5m2!1sen!2sph"},video:[{title:"1. Come arrivare al MLI Hollywood Campus tramite la stazione ferroviaria di Hollywood Highland",youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FrP3AV1P3duU"},{title:"2. Come arrivare al MLI Hollywood Campus in auto \u003Cbr \u002F\u003E\u003Cbr \u002F\u003E",youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FJO2iqyI9Dfc"}],accommodation:{title:"Accommodations",description:["Offriamo la possibilità di alloggiare nei nostri dormitori o aderire al Programma Homestay","＜Dormitory＞\u003Cbr\u002F\u003E","I nostri dormitori si trovano in comode location nei pressi delle nostre sedi"],information:[{yt_link:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002F27o22DzbFp0",desc:["＜Programma Homestay＞ \u003Cbr\u002F\u003E","Questo programma offre il miglior modo per avvicinarsi alla cultura americana e avere la possibilità di parlare in Inglese anche al di fuori dell'ambiente scolastico","\u003Ca href=\"\u002Fit\u002Fstay\u002F\"\u003E\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E Maggiori informazioni sugli alloggi\u003C\u002Fa\u003E"]}]},courses:{title:b,lists:["Programma ESL","TOEFL®","Conversazione","TOEIC®"]},message:{title:"Il Direttore del Campus",image:"\u002Fimages\u002Flocation\u002Fhollywood\u002Fjulie.jpg",position:"Message from Campus Director",description:["Il campus MLI di Hollywood si trova al centro della frenetica Hollywood, a due minuti a piedi dalla stazione metropolitana Hollywood\u002FHighland. Il Dolby Theater, il Chinese Theater e la famosa \"Walk of Fame\" si trovano proprio accanto al nostro campus così come le tantissime opportunità di divertimento che colorano questa zona."]},dir:"\u002Fhollywood",path:"\u002Fhollywood\u002Fit",extension:".json",createdAt:"2026-10-22T16:31:29.554Z",updatedAt:"2025-05-26T12:06:27.778Z"},lang:a}],fetch:{},mutations:void 0}}("it","Corsi")));